-- Seed data for Project Alpha
BEGIN;

TRUNCATE TABLE ticket_tags RESTART IDENTITY CASCADE;
TRUNCATE TABLE tickets RESTART IDENTITY CASCADE;
TRUNCATE TABLE tags RESTART IDENTITY CASCADE;




SELECT setval('tags_id_seq', 20, true);
SELECT setval('tickets_id_seq', 50, true);
SELECT setval('ticket_tags_id_seq', COALESCE((SELECT MAX(id) FROM ticket_tags), 0), true);

COMMIT;
